/**
 * Replaceable first Slack line while the agent is still starting.
 * The authored static line is posted exactly as declared.
 * `chat.startStream` then `stopStream` so the line exists and the chip
 * can paint. An open stream hides `assistant.threads.setStatus`.
 * The first post-update edits that ts. An unclaimed line is deleted
 * when the turn ends.
 */
import { slackDmIsOneSession } from "../../internal/slack-thread-key.js";
import { deleteMessage, postMessage, startChatStream, stopChatStream, updateMessage, } from "./api.js";
import { defaultSlackLog } from "./log.js";
const slots = new Map();
function slotKey(channelId, threadTs) {
    return `${channelId}:${threadTs}`;
}
/** Peer slots that belong to the same session: every slot of a whole-DM session. */
function sessionPeerKeys(channelId, dm) {
    if (!slackDmIsOneSession(channelId, dm)) {
        return [];
    }
    const prefix = `${channelId}:`;
    const keys = [];
    for (const key of slots.keys()) {
        if (key.startsWith(prefix)) {
            keys.push(key);
        }
    }
    return keys;
}
export function resetPlaceholderSlots() {
    slots.clear();
}
function openPlaceholder(key) {
    if (slots.has(key)) {
        return false;
    }
    slots.set(key, { claimed: false, ts: null, streamed: false });
    return true;
}
function takePlaceholder(key) {
    const slot = slots.get(key);
    if (slot === undefined || slot.claimed) {
        return undefined;
    }
    slot.claimed = true;
    if (slot.ts === null) {
        return undefined;
    }
    slots.delete(key);
    return { ts: slot.ts, streamed: slot.streamed };
}
function rememberPlaceholder(key, ts, streamed) {
    const slot = slots.get(key);
    if (slot === undefined || slot.claimed) {
        return false;
    }
    slot.ts = ts;
    slot.streamed = streamed;
    return true;
}
function closePlaceholder(key) {
    const slot = slots.get(key);
    slots.delete(key);
    return slot;
}
async function retractKey(key, args) {
    const closed = closePlaceholder(key);
    if (closed === undefined || closed.claimed || closed.ts === null) {
        return;
    }
    await retractPosted({
        botToken: args.botToken,
        channelId: args.channelId,
        ts: closed.ts,
        streamed: closed.streamed,
        log: args.log,
    });
}
/** Retract only one thread's slot; admission cleanup must not sweep DM peers. */
export async function retractPlaceholderSlot(args) {
    await retractKey(slotKey(args.channelId, args.threadTs), args);
}
export async function finishPlaceholder(args) {
    const first = slotKey(args.channelId, args.threadTs);
    await retractKey(first, args);
    for (const key of sessionPeerKeys(args.channelId, args.dm)) {
        await retractKey(key, args);
    }
}
export function startPlaceholder(args) {
    const key = slotKey(args.channelId, args.threadTs);
    if (!openPlaceholder(key)) {
        return undefined;
    }
    const log = args.log ?? defaultSlackLog;
    return {
        done: postPlaceholder({ ...args, key, log }),
        retract: () => retractKey(key, { ...args, log }),
    };
}
export function adoptPlaceholder(args) {
    const key = slotKey(args.channelId, args.threadTs);
    const existing = slots.get(key);
    if (existing !== undefined &&
        !existing.claimed &&
        existing.ts === args.ts &&
        existing.streamed === (args.streamed === true)) {
        return "already_adopted";
    }
    if (!openPlaceholder(key)) {
        return "occupied";
    }
    return rememberPlaceholder(key, args.ts, args.streamed === true) ? "adopted" : "occupied";
}
/** Delete a control-plane placeholder that this process could not adopt. */
export async function retractPlaceholderMessage(args) {
    await retractPosted(args);
}
async function postPlaceholder(args) {
    try {
        const posted = await postPlaceholderLine(args, args.line);
        if (rememberPlaceholder(args.key, posted.ts, posted.streamed)) {
            args.log.info("placeholder posted", {
                channel: args.channelId,
                thread_ts: args.threadTs,
                message_ts: posted.ts,
                chars: args.line.length,
            });
            return;
        }
        await retractPosted({
            botToken: args.botToken,
            channelId: args.channelId,
            ts: posted.ts,
            streamed: posted.streamed,
            log: args.log,
        });
    }
    catch (error) {
        args.log.warn(`placeholder post failed: ${error instanceof Error ? error.message : String(error)}`, { channel: args.channelId, thread_ts: args.threadTs });
        const closed = closePlaceholder(args.key);
        if (closed === undefined || closed.claimed || closed.ts === null) {
            return;
        }
        await retractPosted({
            botToken: args.botToken,
            channelId: args.channelId,
            ts: closed.ts,
            streamed: closed.streamed,
            log: args.log,
        });
    }
}
async function postPlaceholderLine(args, line) {
    const user = args.recipientUserId;
    const team = args.recipientTeamId;
    const started = await startChatStream({
        botToken: args.botToken,
        channel: args.channelId,
        thread_ts: args.threadTs,
        markdown_text: line,
        recipient_user_id: user === null || user === "" ? undefined : user,
        recipient_team_id: team === null || team === "" ? undefined : team,
    });
    if (started.ok) {
        const stopped = await stopChatStream({
            botToken: args.botToken,
            channel: args.channelId,
            ts: started.ts,
        });
        return { ts: started.ts, streamed: !stopped.ok };
    }
    const posted = await postMessage({
        botToken: args.botToken,
        channel: args.channelId,
        text: line,
        threadTs: args.threadTs,
    });
    return { ts: posted.ts, streamed: false };
}
export async function overlayPlaceholder(args) {
    const primary = slotKey(args.channelId, args.threadTs);
    const painted = await paintSlot(primary, args);
    for (const key of sessionPeerKeys(args.channelId, args.dm)) {
        await paintSlot(key, args);
    }
    return painted;
}
async function paintSlot(key, args) {
    const taken = takePlaceholder(key);
    if (taken === undefined) {
        return undefined;
    }
    if (taken.streamed) {
        await stopChatStream({
            botToken: args.botToken,
            channel: args.channelId,
            ts: taken.ts,
        });
    }
    const result = await updateMessage({
        botToken: args.botToken,
        channel: args.channelId,
        ts: taken.ts,
        text: args.text,
    });
    if (result.ok) {
        return taken.ts;
    }
    await retractPosted({
        botToken: args.botToken,
        channelId: args.channelId,
        ts: taken.ts,
        streamed: false,
    });
    return undefined;
}
async function retractPosted(args) {
    if (args.streamed) {
        await stopChatStream({
            botToken: args.botToken,
            channel: args.channelId,
            ts: args.ts,
        });
    }
    const result = await deleteMessage({
        botToken: args.botToken,
        channel: args.channelId,
        ts: args.ts,
    });
    if (!result.ok) {
        (args.log ?? defaultSlackLog).warn("placeholder retract failed", {
            error: result.error,
            channel: args.channelId,
            ts: args.ts,
        });
    }
}
